function validate([firstList, secondList]) {
  if (firstList.length > 1000 || secondList.length > 1000) return 'Each list has at most 1000 intervals.';
  if (firstList.length + secondList.length < 1) return 'At least one list must contain an interval.';
  for (const list of [firstList, secondList]) {
    for (let i = 0; i < list.length; i++) {
      const [start, end] = list[i];
      if (list[i].length !== 2 || !Number.isInteger(start) || !Number.isInteger(end)) return 'Each interval is a pair of integers [start, end].';
      if (start < 0 || start >= end || end > 1000000000) return 'Each interval needs 0 <= start < end <= 10^9.';
      if (i > 0 && list[i - 1][1] >= start) return 'Within a list, each interval must end before the next one starts.';
    }
  }
  return null;
}

