function intervalIntersection(firstList, secondList) {
  const pieces = [];
  for (const [a, b] of firstList) {
    for (const [c, d] of secondList) {
      const low = a > c ? a : c;
      const high = b < d ? b : d;
      if (low <= high) pieces.push([low, high]);
    }
  }
  return pieces.sort((x, y) => x[0] - y[0]);
}

