function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const makeList = (count, maxGap, maxLength) => {
    const list = [];
    let position = pick(0, maxGap);
    for (let k = 0; k < count; k++) {
      const end = position + pick(1, maxLength);
      list.push([position, end]);
      position = end + pick(1, maxGap);
    }
    return list;
  };
  if (size === 'large') {
    return [makeList(1000, 499999, 499999), makeList(pick(900, 1000), 499999, 499999)];
  }
  const scale = rand() < 0.6 ? 3 : 8;
  let first = pick(0, 5), second = pick(0, 5);
  if (first + second === 0) first = 1;
  return [makeList(first, scale, scale), makeList(second, scale, scale)];
}
